create table if not exists public.accounts_payable(id uuid primary key default gen_random_uuid(),vendor_bill_id uuid not null unique references public.vendor_bill_drafts(id) on delete restrict,supplier_id uuid references public.suppliers(id) on delete set null,customer_id uuid references public.customers(id) on delete set null,invoice_number text,invoice_date date,due_date date,total numeric not null check(total>0),balance_due numeric not null check(balance_due>=0),status text not null default 'open' check(status in ('open','partial','paid','void')),account_code text,memo text,posted_by uuid references public.users(id),posted_at timestamptz not null default now(),created_at timestamptz not null default now());create table if not exists public.ap_payments(id uuid primary key default gen_random_uuid(),accounts_payable_id uuid not null references public.accounts_payable(id) on delete restrict,amount numeric not null check(amount>0),paid_at timestamptz not null,payment_method text not null,reference_number text,notes text,recorded_by uuid references public.users(id),created_at timestamptz not null default now());create table if not exists public.job_cost_allocations(id uuid primary key default gen_random_uuid(),accounts_payable_id uuid not null references public.accounts_payable(id) on delete restrict,job_id uuid not null references public.jobs(id) on delete restrict,amount numeric not null check(amount>0),allocation_type text not null default 'materials' check(allocation_type in ('materials','subcontractor','equipment','permit','other')),notes text,created_by uuid references public.users(id),created_at timestamptz not null default now(),unique(accounts_payable_id,job_id,allocation_type));alter table public.accounts_payable enable row level security;alter table public.ap_payments enable row level security;alter table public.job_cost_allocations enable row level security;create policy "finance read ap" on public.accounts_payable for select to authenticated using(private.current_employee_role() in ('owner','manager','accounting'));create policy "finance manage ap" on public.accounts_payable for all to authenticated using(private.current_employee_role() in ('owner','manager','accounting')) with check(private.current_employee_role() in ('owner','manager','accounting'));create policy "finance read ap payments" on public.ap_payments for select to authenticated using(private.current_employee_role() in ('owner','manager','accounting'));create policy "finance manage ap payments" on public.ap_payments for all to authenticated using(private.current_employee_role() in ('owner','manager','accounting')) with check(private.current_employee_role() in ('owner','manager','accounting'));create policy "finance read allocations" on public.job_cost_allocations for select to authenticated using(private.current_employee_role() in ('owner','manager','accounting'));create policy "finance manage allocations" on public.job_cost_allocations for all to authenticated using(private.current_employee_role() in ('owner','manager','accounting')) with check(private.current_employee_role() in ('owner','manager','accounting'));
create or replace function public.record_ap_payment(p_ap_id uuid,p_amount numeric,p_paid_at timestamptz,p_payment_method text,p_reference text,p_notes text) returns uuid language plpgsql security definer set search_path=public as $$declare u public.users%rowtype;a public.accounts_payable%rowtype;pid uuid;begin select * into u from public.users where auth_user_id=auth.uid() and active=true limit 1;if u.id is null or u.role not in ('owner','manager','accounting') then raise exception 'not authorized';end if;select * into a from public.accounts_payable where id=p_ap_id for update;if a.id is null then raise exception 'AP bill not found';end if;if p_amount<=0 or p_amount>a.balance_due then raise exception 'payment exceeds balance due';end if;insert into public.ap_payments(accounts_payable_id,amount,paid_at,payment_method,reference_number,notes,recorded_by) values(a.id,p_amount,coalesce(p_paid_at,now()),trim(p_payment_method),nullif(trim(p_reference),''),nullif(trim(p_notes),''),u.id) returning id into pid;update public.accounts_payable set balance_due=balance_due-p_amount,status=case when balance_due-p_amount=0 then 'paid' else 'partial' end where id=a.id;insert into public.audit_log(actor_user_id,action,entity_type,entity_id,after_data) values(u.id,'record_ap_payment','accounts_payable',a.id,jsonb_build_object('amount',p_amount,'method',p_payment_method,'reference',p_reference));return pid;end$$;
create or replace function public.allocate_ap_to_job(p_ap_id uuid,p_job_id uuid,p_amount numeric,p_type text,p_notes text) returns uuid language plpgsql security definer set search_path=public as $$declare u public.users%rowtype;a public.accounts_payable%rowtype;j public.jobs%rowtype;allocated numeric;aid uuid;begin select * into u from public.users where auth_user_id=auth.uid() and active=true limit 1;if u.id is null or u.role not in ('owner','manager','accounting') then raise exception 'not authorized';end if;select * into a from public.accounts_payable where id=p_ap_id for update;if a.id is null then raise exception 'AP bill not found';end if;select * into j from public.jobs where id=p_job_id for update;if j.id is null then raise exception 'job not found';end if;if a.customer_id is not null and a.customer_id<>j.customer_id then raise exception 'bill customer does not match job customer';end if;if p_amount<=0 then raise exception 'allocation must be positive';end if;select coalesce(sum(amount),0) into allocated from public.job_cost_allocations where accounts_payable_id=a.id;if allocated+p_amount>a.total then raise exception 'allocation exceeds bill total';end if;insert into public.job_cost_allocations(accounts_payable_id,job_id,amount,allocation_type,notes,created_by) values(a.id,j.id,p_amount,p_type,nullif(trim(p_notes),''),u.id) on conflict(accounts_payable_id,job_id,allocation_type) do update set amount=public.job_cost_allocations.amount+excluded.amount,notes=coalesce(excluded.notes,public.job_cost_allocations.notes) returning id into aid;if p_type='materials' then update public.jobs set material_cost=coalesce(material_cost,0)+p_amount where id=j.id;end if;insert into public.audit_log(actor_user_id,action,entity_type,entity_id,after_data) values(u.id,'allocate_ap_job_cost','job',j.id,jsonb_build_object('accounts_payable_id',a.id,'amount',p_amount,'type',p_type));return aid;end$$;revoke all on function public.record_ap_payment(uuid,numeric,timestamptz,text,text,text) from public,anon;grant execute on function public.record_ap_payment(uuid,numeric,timestamptz,text,text,text) to authenticated;revoke all on function public.allocate_ap_to_job(uuid,uuid,numeric,text,text) from public,anon;grant execute on function public.allocate_ap_to_job(uuid,uuid,numeric,text,text) to authenticated;